import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n % 2 == 0) System.out.println("Even");
            else System.out.println("Odd");
        }
    }
}
